 for(const item of selected){assert(c.lifecycle.restore(root).ok);assert.deepEqual(snapshot(),root,'each branch restores full canonical root and RNG');const branch={name:item.name,quotedRootValue:item.plan.root.value,savedLeafBoundary:item.plan.leaf.boundary,savedActions:item.plan.actions,knownDataClosure:item.suffix,nativeInputs:0,phase:'running'};report.branches.push(branch);persist();for(const id of [...item.plan.actions,...item.suffix])submit(id,branch);const inspected=c.inspect(),state=JSON.parse(snapshot().committedState);assert(inspected.phase!=='awaiting_input','mandatory Decision remains; branch is not settled');assert(state.turn.roundNumber===3&&state.turn.turnNumber>JSON.parse(root.committedState).turn.turnNumber,'both branches must reach the next own turn');assert(state.players.players.find(p=>p.id==='player-white').mainActionCompleted===false,'must not stop before turn end');branch.result=summary();branch.phase='complete';const completed=snapshot();assert(c.lifecycle.restore(completed).ok);assert.deepEqual(snapshot(),completed,'full branch checkpoint cold-restores exactly');branch.coldRestoreExact=true;persist();}
 assert(c.lifecycle.restore(root).ok);assert.deepEqual(snapshot(),root,'source root and RNG restored at exit');report.rootAndRngRestoredAtExit=true;report.phase='complete';report.unknownCardIdentityNotUsedToSelectActions=true;report.assetResultsAreNotWholeGameScores=true;persist();console.log(JSON.stringify({phase:report.phase,branchNativeInputs:report.branchNativeInputs,branches:report.branches.map(b=>({name:b.name,nativeInputs:b.nativeInputs,score:b.result.score,projectedFinal:b.result.currentProjectedFinalScore,resources:b.result.resources,income:b.result.income,tech:b.result.technology.ownedTiles,hand:b.result.hand}))}));
